<span class="line"><span style="color:#E06C75;font-style:italic;">            urgency</span><span style="color:#56B6C2;">=</span><span style="color:#E5C07B;">self</span><span style="color:#ABB2BF;">.</span><span style="color:#61AFEF;">_determine_urgency</span><span style="color:#ABB2BF;">(part, inventory),</span></span>
